/**
 * Make `<hermes/hermes.h>` resolvable for every pod.
 *
 * expo-modules-jsi 57.1.x (and Expo / React-hermes, which include the same
 * header) look under `Pods/Headers/Public/hermes-engine/hermes/`, but the
 * prebuilt hermes-engine pod does not mirror its headers there — they only
 * exist in `Pods/hermes-engine/destroot/include`. `ios/` is regenerated by
 * prebuild, so the fix lives in the Podfile `post_install` hook.
 */

const { withPodfile } = require('expo/config-plugins');

const MARKER = 'waves:hermes-headers';

const SNIPPET = `
    # ${MARKER} — see plugins/withHermesHeaders.js
    hermes_include = File.join(installer.sandbox.root.to_s, 'hermes-engine/destroot/include')
    hermes_link = File.join(installer.sandbox.root.to_s, 'Headers/Public/hermes-engine')
    if File.directory?(hermes_include) && !File.exist?(hermes_link)
      FileUtils.mkdir_p(File.dirname(hermes_link))
      File.symlink('../../hermes-engine/destroot/include', hermes_link)
    end
    installer.pods_project.targets.each do |target|
      target.build_configurations.each do |config|
        paths = Array(config.build_settings['HEADER_SEARCH_PATHS'] || '$(inherited)')
        entry = '"$(PODS_ROOT)/hermes-engine/destroot/include"'
        config.build_settings['HEADER_SEARCH_PATHS'] = [entry] + paths unless paths.include?(entry)
      end
    end
`;

/** Inject after the (multi-line) react_native_post_install call; no-op if already there. */
function injectHermesHeaders(contents) {
  if (contents.includes(MARKER)) return contents;
  const re = /(react_native_post_install\([\s\S]*?\n\s*\)\n)/;
  if (!re.test(contents)) {
    throw new Error('withHermesHeaders: react_native_post_install call not found in Podfile');
  }
  return contents.replace(re, (m) => m + SNIPPET);
}

module.exports = function withHermesHeaders(config) {
  return withPodfile(config, (c) => {
    c.modResults.contents = injectHermesHeaders(c.modResults.contents);
    return c;
  });
};
module.exports._internals = { injectHermesHeaders, MARKER };
